function wait(ms, value) {
  return new Promise((resolve) => setTimeout(() => resolve(value), ms));
}

async function run() {
  try {
    const a = await wait(400, "а");
    const b = await wait(400, "б");
    console.log(a, b);
    const both = await Promise.all([wait(200, 1), wait(200, 2)]);
    console.log(both);
  } catch (error) {
    console.error(error);
  } finally {
    console.log("конец");
  }
}

run();
